pub export fn maximal_square(a:[*c]const i64,len:usize)i64{if(a==null or len<3 or len>258)return -1;if(a[0]<1 or a[0]>16 or a[1]<1 or a[1]>16 or len!=@as(usize,@intCast(a[0]*a[1]))+2)return -1;const rows:usize=@intCast(a[0]);const cols:usize=@intCast(a[1]);var dp=[_]usize{0}**16;var best:usize=0;for(0..rows*cols)|i|if(a[i+2]!=0 and a[i+2]!=1)return -1;for(0..rows)|r|{var diag:usize=0;for(0..cols)|c|{const above=dp[c];if(a[r*cols+c+2]==1){dp[c]=if(r==0 or c==0) 1 else @min(@min(diag,dp[c]),dp[c-1])+1;best=@max(best,dp[c]);}else{dp[c]=0;}diag=above;}}return @intCast(best*best);}
